class stringx
{
    char data[16];
public:
    stringx(const stringx &);
    ~stringx();
    void to_upper();
};

struct entry_vtable
{
    char pad0[40];
    short disable_adjust;
    short pad1;
    void (*disable)(void *, bool);
    char pad2[88];
    short text_adjust;
    short pad3;
    void (*set_text)(void *, stringx);
};

struct menu_entry
{
    char pad[96];
    entry_vtable *vtable;
};

struct text_vtable
{
    char pad[72];
    short change_adjust;
    short pad1;
    void (*change_text)(void *, stringx);
};

struct box_text
{
    char pad[76];
    text_vtable *vtable;
    void makeBox(int, int, bool = false, float = -1.0f, int = -1);
};

struct menu_vtable
{
    char pad[24];
    short high_adjust;
    short pad1;
    void (*set_high)(void *, menu_entry *, bool);
};

struct GenericGameSaver
{
    stringx getSavingString(int, int, stringx);
};

extern GenericGameSaver *game_saver;
extern int savePort;
extern int saveSlot;
extern stringx ksGlobalTextArray[];

__asm__(".equ game_saver,0x0041E5B8");
__asm__(".equ savePort,0x0041E5AC");
__asm__(".equ saveSlot,0x0041E5B0");
__asm__(".equ ksGlobalTextArray,0x003E6490");

struct SaveCareerPromptClass
{
    char pad0[116];
    menu_vtable *vtable;
    int frame_timer;
    int state;
    int next_menu;
    menu_entry *yes;
    menu_entry *no;
    box_text *message;
};

extern "C" void set_state(SaveCareerPromptClass *, int)
    __asm__("SetState__21SaveCareerPromptClassi");

void set_state(SaveCareerPromptClass *self, int state)
{
    self->state = state;

    if (self->state == 2)
    {
        stringx tmp = game_saver->getSavingString(savePort, saveSlot, ksGlobalTextArray[1]);
        tmp.to_upper();
        text_vtable *text = self->message->vtable;
        text->change_text((char *)self->message + text->change_adjust, tmp);
        self->message->makeBox(400, 300);
        entry_vtable *entry = self->yes->vtable;
        entry->disable((char *)self->yes + entry->disable_adjust, true);
        entry = self->no->vtable;
        entry->disable((char *)self->no + entry->disable_adjust, true);
    }
    else if (self->state == 0)
    {
        stringx tmp = game_saver->getSavingString(savePort, saveSlot, ksGlobalTextArray[424]);
        tmp.to_upper();
        text_vtable *text = self->message->vtable;
        text->change_text((char *)self->message + text->change_adjust, tmp);
        self->message->makeBox(400, 300);
        entry_vtable *entry = self->yes->vtable;
        entry->disable((char *)self->yes + entry->disable_adjust, true);
        entry = self->no->vtable;
        entry->disable((char *)self->no + entry->disable_adjust, true);
    }
    else if (self->state == 4)
    {
        self->frame_timer = 3;
        stringx tmp = game_saver->getSavingString(savePort, saveSlot, ksGlobalTextArray[0]);
        tmp.to_upper();
        text_vtable *text = self->message->vtable;
        text->change_text((char *)self->message + text->change_adjust, tmp);
        self->message->makeBox(400, 300);
        entry_vtable *entry = self->yes->vtable;
        entry->disable((char *)self->yes + entry->disable_adjust, true);
        entry = self->no->vtable;
        entry->disable((char *)self->no + entry->disable_adjust, true);
    }
    else if (self->state == 6)
    {
        stringx tmp = ksGlobalTextArray[174];
        text_vtable *text = self->message->vtable;
        text->change_text((char *)self->message + text->change_adjust, tmp);
        self->message->makeBox(400, 300);
        entry_vtable *entry = self->no->vtable;
        entry->disable((char *)self->no + entry->disable_adjust, false);
        tmp = ksGlobalTextArray[162];
        entry = self->no->vtable;
        entry->set_text((char *)self->no + entry->text_adjust, tmp);
        menu_vtable *menu = self->vtable;
        menu->set_high((char *)self + menu->high_adjust, self->no, true);
    }
}
